package com.runeshopvalue;

import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.ItemID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;

import java.util.Map;

public class RunePouchReader
{
    private static final int NUM_SLOTS = 6;

    private static final int[] AMOUNT_VARBITS = {
            VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3,
            VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6
    };

    private static final int[] RUNE_VARBITS = {
            VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
            VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6
    };

    private static final int[] POUCH_ITEM_IDS = {
            ItemID.RUNE_POUCH,
            ItemID.RUNE_POUCH_L,
            ItemID.DIVINE_RUNE_POUCH,
            ItemID.DIVINE_RUNE_POUCH_L
    };

    public static void addPouchContents(Client client, Map<Integer, Integer> runeCounts)
    {
        var inventory = client.getItemContainer(InventoryID.INV);
        if (inventory == null)
        {
            return;
        }

        boolean hasPouch = false;
        for (int id : POUCH_ITEM_IDS)
        {
            if (inventory.contains(id))
            {
                hasPouch = true;
                break;
            }
        }
        if (!hasPouch)
        {
            return;
        }

        EnumComposition runepouchEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);

        for (int i = 0; i < NUM_SLOTS; i++)
        {
            int amount = client.getVarbitValue(AMOUNT_VARBITS[i]);
            int runeIndex = client.getVarbitValue(RUNE_VARBITS[i]);

            if (amount <= 0 || runeIndex == 0)
            {
                continue;
            }

            int runeItemId = runepouchEnum.getIntValue(runeIndex);
            if (RunePrices.PRICES.containsKey(runeItemId))
            {
                runeCounts.merge(runeItemId, amount, Integer::sum);
            }
        }
    }
}

package com.runeshopvalue;

import net.runelite.api.ItemID;

import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class RunePrices
{
    // Ali Morrisane's Discount Wares — static "buys at" price per rune.
    // Anything not in this map isn't purchased by this shop.
    public static final Map<Integer, Integer> PRICES = new HashMap<>();

    // Ordered lowest to highest Runecraft level required to craft.
    public static final List<Integer> ELEMENTAL_ORDER = Arrays.asList(
            ItemID.AIR_RUNE,   // lvl 1
            ItemID.WATER_RUNE, // lvl 5
            ItemID.EARTH_RUNE, // lvl 9
            ItemID.FIRE_RUNE   // lvl 14
    );

    public static final List<Integer> CATALYTIC_ORDER = Arrays.asList(
            ItemID.MIND_RUNE,   // lvl 1
            ItemID.BODY_RUNE,   // lvl 20
            ItemID.COSMIC_RUNE, // lvl 27
            ItemID.CHAOS_RUNE,  // lvl 35
            ItemID.NATURE_RUNE, // lvl 44
            ItemID.LAW_RUNE,    // lvl 54
            ItemID.DEATH_RUNE,  // lvl 65
            ItemID.BLOOD_RUNE,  // lvl 77
            ItemID.SOUL_RUNE    // lvl 90
    );

    static
    {
        PRICES.put(ItemID.AIR_RUNE, 2);
        PRICES.put(ItemID.WATER_RUNE, 2);
        PRICES.put(ItemID.EARTH_RUNE, 2);
        PRICES.put(ItemID.FIRE_RUNE, 2);

        PRICES.put(ItemID.MIND_RUNE, 1);
        PRICES.put(ItemID.BODY_RUNE, 1);
        PRICES.put(ItemID.COSMIC_RUNE, 25);
        PRICES.put(ItemID.CHAOS_RUNE, 45);
        PRICES.put(ItemID.NATURE_RUNE, 90);
        PRICES.put(ItemID.DEATH_RUNE, 90);
        PRICES.put(ItemID.LAW_RUNE, 120);
        PRICES.put(ItemID.SOUL_RUNE, 150);
        PRICES.put(ItemID.BLOOD_RUNE, 200);
    }
}

package com.runeshopvalue;

import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

import javax.inject.Inject;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;

public class RuneShopInventoryTooltipOverlay extends Overlay
{
    private final Client client;
    private final RuneShopValueConfig config;
    private final TooltipManager tooltipManager;

    @Inject
    public RuneShopInventoryTooltipOverlay(Client client, RuneShopValueConfig config, TooltipManager tooltipManager)
    {
        this.client = client;
        this.config = config;
        this.tooltipManager = tooltipManager;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showInventoryTooltip())
        {
            return null;
        }

        Widget inventoryWidget = client.getWidget(InterfaceID.Inventory.ITEMS);
        if (inventoryWidget == null || inventoryWidget.isHidden())
        {
            return null;
        }

        Widget[] slots = inventoryWidget.getDynamicChildren();
        if (slots == null)
        {
            return null;
        }

        Point mouse = client.getMouseCanvasPosition();
        if (mouse == null)
        {
            return null;
        }

        ItemContainer inventory = client.getItemContainer(InventoryID.INV);
        if (inventory == null)
        {
            return null;
        }

        Item[] items = inventory.getItems();

        for (Widget slot : slots)
        {
            Rectangle bounds = slot.getBounds();
            if (bounds == null || !bounds.contains(mouse.getX(), mouse.getY()))
            {
                continue;
            }

            int index = slot.getIndex();
            if (index < 0 || index >= items.length)
            {
                return null;
            }

            Item item = items[index];
            if (item == null)
            {
                return null;
            }

            Integer price = RunePrices.PRICES.get(item.getId());
            if (price == null)
            {
                return null;
            }

            long value = (long) item.getQuantity() * price;
            tooltipManager.add(new Tooltip(String.format("ALI: %,d gp (%,d ea)", value, price)));
            return null;
        }

        return null;
    }
}

package com.runeshopvalue;

import net.runelite.client.config.Config;
