package com.runeshopvalue;

import net.runelite.api.Client;
import net.runelite.api.ItemID;
import net.runelite.api.Point;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

import javax.inject.Inject;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class RuneShopValueOverlay extends Overlay
{
    private static final int ICON_SIZE = 32;
    private static final int PADDING = 4;

    private final Client client;
    private final ItemManager itemManager;
    private final RuneShopValueConfig config;
    private final TooltipManager tooltipManager;

    private Map<Integer, Integer> runeCounts = new HashMap<>();

    @Inject
    public RuneShopValueOverlay(Client client, ItemManager itemManager, RuneShopValueConfig config, TooltipManager tooltipManager)
    {
        this.client = client;
        this.itemManager = itemManager;
        this.config = config;
        this.tooltipManager = tooltipManager;
        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    public void updateRuneCounts(Map<Integer, Integer> counts)
    {
        this.runeCounts = new HashMap<>(counts);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showOverlay() || runeCounts.isEmpty())
        {
            return null;
        }

        boolean horizontal = config.overlayOrientation() == OverlayOrientation.HORIZONTAL;
        boolean totalOnly = config.overlayTotalOnly();

        List<Integer> orderedIds = new ArrayList<>();
        orderedIds.addAll(RunePrices.ELEMENTAL_ORDER);
        orderedIds.addAll(RunePrices.CATALYTIC_ORDER);

        Rectangle overlayBounds = getBounds();
        Point mouse = client.getMouseCanvasPosition();

        int x = 0;
        int y = 0;
        long total = 0;
        int maxX = 0;
        int maxY = 0;

        StringBuilder breakdown = new StringBuilder();

        for (int itemId : orderedIds)
        {
            Integer quantity = runeCounts.get(itemId);
            if (quantity == null || quantity <= 0)
            {
                continue;
            }

            int price = RunePrices.PRICES.getOrDefault(itemId, 0);
            long value = (long) quantity * price;
            total += value;

            if (totalOnly)
            {
                String runeName = itemManager.getItemComposition(itemId).getName();
                if (breakdown.length() > 0)
                {
                    breakdown.append("</br>");
                }
                breakdown.append(String.format("%,d x %s: %,d gp", quantity, runeName, value));
                continue;
            }

            BufferedImage runeImg = itemManager.getImage(itemId, quantity, true);
            if (runeImg != null)
            {
                graphics.drawImage(runeImg, x, y, null);
            }
            String runeName = itemManager.getItemComposition(itemId).getName();
            checkTooltip(overlayBounds, mouse, x, y, String.format("%,d x %s", quantity, runeName));
            x += ICON_SIZE + PADDING;

            int coinQty = (int) Math.min(value, Integer.MAX_VALUE);
            BufferedImage coinImg = itemManager.getImage(ItemID.COINS_995, coinQty, true);
            if (coinImg != null)
            {
                graphics.drawImage(coinImg, x, y, null);
            }
            checkTooltip(overlayBounds, mouse, x, y, String.format("%,d gp", value));

            if (horizontal)
            {
                x += ICON_SIZE + PADDING * 3;
                maxX = Math.max(maxX, x);
                maxY = Math.max(maxY, y + ICON_SIZE);
            }
            else
            {
                x = 0;
                y += ICON_SIZE + PADDING;
                maxX = ICON_SIZE * 2 + PADDING;
                maxY = y;
            }
        }

        if (totalOnly || config.showOverlayTotal())
        {
            int totalCoins = (int) Math.min(total, Integer.MAX_VALUE);
            BufferedImage totalCoinImg = itemManager.getImage(ItemID.COINS_995, totalCoins, true);
            if (totalCoinImg != null)
            {
                graphics.drawImage(totalCoinImg, x, y, null);
            }

            String tooltipText = totalOnly
                    ? String.format("Total: %,d gp</br>%s", total, breakdown)
                    : String.format("Total: %,d gp", total);
            checkTooltip(overlayBounds, mouse, x, y, tooltipText);

            maxX = Math.max(maxX, x + ICON_SIZE);
            maxY = Math.max(maxY, y + ICON_SIZE + (horizontal ? 0 : PADDING));
        }

        return new Dimension(maxX, maxY);
    }

    private void checkTooltip(Rectangle overlayBounds, Point mouse, int x, int y, String text)
    {
        if (overlayBounds == null || mouse == null)
        {
            return;
        }

        Rectangle iconBounds = new Rectangle(overlayBounds.x + x, overlayBounds.y + y, ICON_SIZE, ICON_SIZE);
        if (iconBounds.contains(mouse.getX(), mouse.getY()))
        {
            tooltipManager.add(new Tooltip(text));
        }
    }
}

package com.runeshopvalue;

import net.runelite.api.ItemID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.PluginPanel;

import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.Map;

public class RuneShopValuePanel extends PluginPanel
{
    private final JPanel listPanel = new JPanel();
    private final JLabel totalCoinLabel = new JLabel();
    private final ItemManager itemManager;

    public RuneShopValuePanel(ItemManager itemManager)
    {
        this.itemManager = itemManager;

        setLayout(new BorderLayout());
        listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
        add(new JScrollPane(listPanel), BorderLayout.CENTER);

        JPanel totalPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 4));
        totalPanel.add(totalCoinLabel);
        add(totalPanel, BorderLayout.SOUTH);
    }

    public void update(Map<Integer, Integer> runeCounts)
    {
        listPanel.removeAll();
        long total = 0;

        total += addSection("Elemental", RunePrices.ELEMENTAL_ORDER, runeCounts);
        total += addSection("Catalytic", RunePrices.CATALYTIC_ORDER, runeCounts);

        int totalCoins = (int) Math.min(total, Integer.MAX_VALUE);
        BufferedImage totalCoinImg = itemManager.getImage(ItemID.COINS_995, totalCoins, true);
        totalCoinLabel.setIcon(new ImageIcon(totalCoinImg));
        totalCoinLabel.setToolTipText(String.format("Total: %,d gp", total));

        listPanel.revalidate();
        listPanel.repaint();
        revalidate();
        repaint();
    }

    private long addSection(String title, List<Integer> order, Map<Integer, Integer> runeCounts)
    {
        long sectionTotal = 0;
        boolean headerAdded = false;

        for (int itemId : order)
        {
            Integer quantity = runeCounts.get(itemId);
            if (quantity == null || quantity <= 0)
            {
                continue;
            }

            if (!headerAdded)
            {
                JLabel header = new JLabel(title);
                header.setFont(header.getFont().deriveFont(Font.BOLD, 13f));
                header.setBorder(BorderFactory.createEmptyBorder(6, 4, 2, 0));
                listPanel.add(header);
                headerAdded = true;
            }

            int price = RunePrices.PRICES.getOrDefault(itemId, 0);
            long value = (long) quantity * price;
            sectionTotal += value;

            listPanel.add(buildRow(itemId, quantity, value));
        }

        return sectionTotal;
    }

    private JPanel buildRow(int itemId, int quantity, long value)
    {
        JPanel row = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 4));

        BufferedImage runeImg = itemManager.getImage(itemId, quantity, true);
        row.add(new JLabel(new ImageIcon(runeImg)));

        int coinQuantity = (int) Math.min(value, Integer.MAX_VALUE);
        BufferedImage coinImg = itemManager.getImage(ItemID.COINS_995, coinQuantity, true);
        row.add(new JLabel(new ImageIcon(coinImg)));

        row.add(new JLabel(String.format("%,d gp", value)));

        return row;
    }
}

package com.runeshopvalue;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemID;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.AsyncBufferedImage;

import java.util.HashMap;
import java.util.Map;

@PluginDescriptor(
        name = "Rune Shop Value",
        description = "Shows the sell value of your runes at Ali Morrisane's shop",
        tags = {"runes", "value", "ali morrisane", "shop"}
)
public class RuneShopValuePlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private RuneShopValueConfig config;

    @Inject
    private ItemManager itemManager;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private RuneShopValueOverlay overlay;

    @Inject
    private RuneShopInventoryTooltipOverlay inventoryTooltipOverlay;

    private RuneShopValuePanel panel;
    private NavigationButton navButton;

    @Provides
    RuneShopValueConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(RuneShopValueConfig.class);
    }

    @Override
    protected void startUp()
    {
        panel = new RuneShopValuePanel(itemManager);

        AsyncBufferedImage icon = itemManager.getImage(ItemID.LAW_RUNE);

        navButton = NavigationButton.builder()
                .tooltip("Rune Shop Value")
                .icon(icon)
                .priority(6)
                .panel(panel)
                .build();

        clientToolbar.addNavigation(navButton);

        // The sprite often isn't loaded yet at this point (you're not logged in yet),
        // so force the sidebar to redraw this icon once it actually finishes loading.
        icon.onLoaded(() ->
        {
            clientToolbar.removeNavigation(navButton);
            clientToolbar.addNavigation(navButton);
        });

        overlayManager.add(overlay);
        overlayManager.add(inventoryTooltipOverlay);
    }

    @Override
    protected void shutDown()
    {
        clientToolbar.removeNavigation(navButton);
        overlayManager.remove(overlay);
        overlayManager.remove(inventoryTooltipOverlay);
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        Map<Integer, Integer> runeCounts = new HashMap<>();

        ItemContainer inventory = client.getItemContainer(InventoryID.INV);
        if (inventory != null)
        {
            for (Item item : inventory.getItems())
            {
                if (RunePrices.PRICES.containsKey(item.getId()) && isEnabled(item.getId()))
                {
                    runeCounts.merge(item.getId(), item.getQuantity(), Integer::sum);
                }
            }
        }

        if (config.includeRunePouch())
        {
            RunePouchReader.addPouchContents(client, runeCounts);
            runeCounts.keySet().removeIf(id -> !isEnabled(id));
        }

        panel.update(runeCounts);
        overlay.updateRuneCounts(runeCounts);
    }

    private boolean isEnabled(int itemId)
    {
        if (itemId == ItemID.AIR_RUNE) return config.showAir();
        if (itemId == ItemID.WATER_RUNE) return config.showWater();
        if (itemId == ItemID.EARTH_RUNE) return config.showEarth();
        if (itemId == ItemID.FIRE_RUNE) return config.showFire();
        if (itemId == ItemID.MIND_RUNE) return config.showMind();
        if (itemId == ItemID.BODY_RUNE) return config.showBody();
        if (itemId == ItemID.COSMIC_RUNE) return config.showCosmic();
        if (itemId == ItemID.CHAOS_RUNE) return config.showChaos();
        if (itemId == ItemID.NATURE_RUNE) return config.showNature();
        if (itemId == ItemID.LAW_RUNE) return config.showLaw();
        if (itemId == ItemID.DEATH_RUNE) return config.showDeath();
        if (itemId == ItemID.BLOOD_RUNE) return config.showBlood();
        if (itemId == ItemID.SOUL_RUNE) return config.showSoul();
        return true;
    }
}

